/* ═══════════════════════════════════════════════════════════════════
   SUNKUU 360 — Centro de Exportación · v3
   Tokens: --navy #00008C · --teal #00EBC8 · --bg #EBF0F7 · --brd #D4E0EE
   v3: variables :root, hardcoded→tokens, legibilidad mejorada,
       emojis→Material Icons
   ═══════════════════════════════════════════════════════════════════ */

#exp-root {
  --navy: #00008C;
  --teal: #00EBC8;
  --bg:   #EBF0F7;
  --surf: #FFFFFF;
  --pri:  #0D1B2E;
  --sec:  #5A6E8A;
  --ter:  #96AABF;
  --brd:  #D4E0EE;
  --pos:  #10B981;
  --neg:  #EF4444;
  --warn: #F59E0B;
  --ind:  #6366F1;
  --shd:  0 1px 3px rgba(13,27,46,.06), 0 8px 28px rgba(13,27,46,.08);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

#exp-root {
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  background: var(--bg);
  height: auto;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
}

/* ── HEADER ────────────────────────────────────────────────────────── */
#exp-header {
  background: var(--navy);
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  box-shadow: 0 2px 14px rgba(0,0,0,.32);
}

#exp-header-left {
  display: flex;
  align-items: center;
  gap: 14px;
}

#exp-logo {
  display: flex;
  align-items: center;
  gap: 8px;
}

#exp-logo-text {
  font-weight: 800;
  font-size: 16px;
  letter-spacing: -.01em;
  color: white;
}
.logo-teal { color: var(--teal); }
.logo-sub  { font-weight: 400; font-size: 9px; color: rgba(255,255,255,.35); margin-left: 4px; letter-spacing: .05em; }

#exp-title {
  font-size: 17px;
  font-weight: 800;
  color: white;
  letter-spacing: -.02em;
  line-height: 1.1;
}

#exp-subtitle {
  font-size: 11px;
  color: rgba(255,255,255,.6);
  margin-top: 3px;
}

/* ── BODY ──────────────────────────────────────────────────────────── */
#exp-body {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 18px;
  padding: 20px 24px 32px;
  align-items: start;
  flex: 1;
}

/* ── SECCIONES ─────────────────────────────────────────────────────── */
.exp-section {
  background: var(--surf);
  border-radius: 16px;
  border: 1px solid var(--brd);
  box-shadow: var(--shd);
  padding: 18px 20px;
  margin-bottom: 14px;
}
.exp-section:last-child { margin-bottom: 0; }

.section-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.sec-num {
  width: 28px; height: 28px;
  border-radius: 7px;
  background: linear-gradient(135deg, var(--navy), #0a0abb);
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 800; color: var(--teal);
  flex-shrink: 0;
  box-shadow: 0 2px 8px rgba(0,0,140,.25);
}
.sec-num-sm { font-size: 14px; }

.sec-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: -.01em;
}

/* ── INSTALACIÓN: TARJETAS ─────────────────────────────────────────── */
#inst-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.inst-card {
  border: 2px solid var(--brd);
  border-radius: 12px;
  padding: 12px 13px;
  cursor: pointer;
  background: var(--surf);
  text-align: left;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  transition: all .15s;
  width: 100%;
}
.inst-card:hover:not(.offline) {
  border-color: var(--teal);
  background: rgba(0,235,200,.04);
}
.inst-card.active {
  border-color: var(--teal);
  background: rgba(0,235,200,.06);
  box-shadow: 0 0 0 3px rgba(0,235,200,.18);
}
.inst-card.offline {
  opacity: .55;
  cursor: not-allowed;
}

.inst-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  margin-top: 3px; flex-shrink: 0;
}
.inst-dot.online  { background: var(--pos); box-shadow: 0 0 4px rgba(16,185,129,.7); }
.inst-dot.offline { background: var(--neg); }

.inst-info  { flex: 1; min-width: 0; }
.inst-name  { font-size: 12px; font-weight: 700; color: var(--pri); line-height: 1.2; }
.inst-client{ font-size: 10px; color: var(--sec); margin-top: 2px; }

.inst-badge {
  display: inline-block;
  margin-top: 5px;
  padding: 2px 7px;
  border-radius: 20px;
  font-size: 9px; font-weight: 700;
}
.inst-badge.em      { background: rgba(0,0,140,.08); color: var(--navy); }
.inst-badge.piscina { background: #EEF2FF; color: var(--ind); }

/* ── VARIABLES: GRUPOS Y PILLS ─────────────────────────────────────── */
#var-controls {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-left: auto;
  flex-wrap: wrap;
}

.ctrl-btn {
  padding: 4px 12px;
  border-radius: 7px;
  border: 1px solid var(--brd);
  background: transparent;
  cursor: pointer;
  font-size: 11px; font-weight: 600;
  color: var(--navy);
}
.ctrl-btn:hover { background: rgba(0,0,140,.06); }

.var-counter {
  font-size: 11px; font-weight: 700;
  color: var(--navy);
  background: rgba(0,235,200,.12);
  border: 1px solid rgba(0,235,200,.28);
  padding: 4px 10px;
  border-radius: 7px;
}

.var-group       { margin-bottom: 12px; }
.var-group:last-child { margin-bottom: 0; }

.var-group-title {
  font-size: 10px; font-weight: 700;
  letter-spacing: .07em; text-transform: uppercase;
  color: var(--sec);
  margin-bottom: 7px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--brd);
}

.var-pills { display: flex; flex-wrap: wrap; gap: 6px; }

.var-pill {
  display: flex; align-items: center; gap: 5px;
  padding: 5px 11px;
  border-radius: 20px;
  border: 1px solid var(--brd);
  background: transparent;
  cursor: pointer;
  font-size: 11px; font-weight: 500;
  color: var(--sec);
  transition: all .12s;
  user-select: none;
}
.var-pill input { display: none; }
.var-pill:hover { border-color: var(--teal); color: var(--navy); }

.var-pill.checked {
  border-color: var(--teal);
  background: rgba(0,235,200,.1);
  color: var(--navy);
  font-weight: 600;
}

.pill-check { font-size: 10px; color: var(--teal); display: none; }
.var-pill.checked .pill-check { display: inline; }

/* ── PERÍODO ───────────────────────────────────────────────────────── */
#period-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.field-label {
  font-size: 12px; font-weight: 600;
  color: var(--sec);
  margin-bottom: 7px;
}

#date-row {
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 10px;
}

.date-field { flex: 1; }
.date-label { font-size: 10px; color: var(--sec); margin-bottom: 4px; }

.date-input {
  width: 100%;
  background: #F0F6FC;
  border: 1px solid var(--brd);
  border-radius: 8px;
  padding: 7px 10px;
  font-size: 11px; color: var(--pri); font-weight: 600;
  cursor: pointer;
}
.date-input:focus { outline: none; border-color: var(--teal); }

.date-sep { font-size: 12px; color: var(--sec); flex-shrink: 0; }

#quick-btns { display: flex; gap: 6px; flex-wrap: wrap; }
.quick-btn {
  padding: 5px 11px;
  border-radius: 7px;
  border: 1px solid var(--brd);
  background: transparent;
  cursor: pointer;
  font-size: 11px; font-weight: 600;
  color: var(--sec);
  transition: all .12s;
}
.quick-btn:hover { border-color: var(--navy); background: rgba(0,0,140,.06); color: var(--navy); }
.quick-btn.active { border-color: var(--navy); background: var(--navy); color: white; }

.gran-select {
  width: 100%;
  background: #F0F6FC;
  border: 1px solid var(--brd);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 11px; color: var(--pri); font-weight: 600;
  cursor: pointer;
}
.gran-select:focus { outline: none; border-color: var(--teal); }

.agg-wrap { transition: opacity .2s; }
.agg-wrap.disabled { opacity: .4; pointer-events: none; }

.raw-warning {
  font-size: 11px;
  color: var(--warn);
  background: rgba(245,158,11,.08);
  border: 1px solid rgba(245,158,11,.22);
  border-radius: 7px;
  padding: 6px 10px;
  margin-top: 8px;
}

.tip-box {
  margin-top: 10px;
  padding: 8px 11px;
  background: rgba(0,235,200,.06);
  border: 1px solid rgba(0,235,200,.18);
  border-radius: 8px;
  font-size: 10px; color: var(--sec);
  line-height: 1.5;
  display: flex; align-items: flex-start; gap: 6px;
}
.tip-ico {
  font-family: 'Material Icons';
  font-size: 16px; color: var(--teal);
  font-style: normal; font-weight: normal;
  line-height: 1.4; user-select: none; flex-shrink: 0;
}

/* ── RESUMEN ───────────────────────────────────────────────────────── */
.summ-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 8px 0;
  border-bottom: 1px solid var(--brd);
  gap: 8px;
}
.summ-row:last-child { border-bottom: none; }

.summ-label { font-size: 12px; color: var(--sec); flex-shrink: 0; }
.summ-val   { font-size: 12px; font-weight: 600; color: var(--pri); text-align: right; font-variant-numeric: tabular-nums; }

/* ── BOTÓN EXPORTAR ────────────────────────────────────────────────── */
#btn-export {
  width: 100%;
  background: var(--teal);
  border: none;
  border-radius: 14px;
  padding: 15px 24px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  box-shadow: 0 4px 16px rgba(0,235,200,.4);
  transition: all .2s;
  margin-bottom: 12px;
}
#btn-export:hover:not(:disabled) {
  background: #00d4b4;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(0,235,200,.5);
}
#btn-export:disabled {
  background: #CBD5E1;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}
#btn-icon {
  font-family: 'Material Icons';
  font-size: 20px; font-style: normal; font-weight: normal;
  line-height: 1; user-select: none;
  color: var(--navy);
}
#btn-text { font-size: 14px; font-weight: 700; color: var(--navy); }

/* ── PROGRESO ──────────────────────────────────────────────────────── */
#exp-progress { flex-direction: column; gap: 6px; margin-bottom: 10px; }

#progress-bar-track {
  width: 100%; height: 6px;
  background: var(--brd);
  border-radius: 3px; overflow: hidden;
}
#progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--navy), var(--teal));
  border-radius: 3px;
  width: 0%;
  transition: width .3s ease;
}
#progress-label { font-size: 11px; color: var(--sec); font-weight: 500; }

/* ── RESULTADO ─────────────────────────────────────────────────────── */
.exp-result {
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 12px; font-weight: 600;
  line-height: 1.4;
}
.exp-result.success {
  background: #ECFDF5;
  border: 1px solid rgba(16,185,129,.3);
  color: #065F46;
}
.exp-result.error {
  background: #FEF2F2;
  border: 1px solid rgba(239,68,68,.3);
  color: #991B1B;
}

/* ── HISTORIAL ─────────────────────────────────────────────────────── */
.hist-note { font-size: 10px; color: var(--ter); margin-left: auto; font-style: italic; }

.hist-empty {
  font-size: 12px; color: var(--ter);
  text-align: center; padding: 14px 0; font-style: italic;
}

.hist-item {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 0;
  border-top: 1px solid var(--brd);
}
.hist-info  { flex: 1; min-width: 0; }
.hist-label { font-size: 12px; font-weight: 600; color: var(--pri); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hist-meta  { font-size: 11px; color: var(--sec); margin-top: 2px; }
.hist-fecha { font-size: 10px; color: var(--ter); }

.hist-btn {
  font-size: 11px; font-weight: 700;
  color: var(--navy);
  background: rgba(0,0,140,.07);
  border: 1px solid rgba(0,0,140,.15);
  border-radius: 6px;
  padding: 4px 9px;
  cursor: pointer; flex-shrink: 0;
}
.hist-btn:hover { background: rgba(0,0,140,.13); }

/* ── BOTÓN VOLVER ──────────────────────────────────────────────────── */
#btn-back {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 8px;
  padding: 6px 12px;
  cursor: pointer;
  color: rgba(255,255,255,.8);
  font-size: 12px; font-weight: 700;
  font-family: inherit;
  transition: all .15s;
  flex-shrink: 0; white-space: nowrap;
  display: flex; align-items: center; gap: 6px;
}
#btn-back:hover { background: rgba(255,255,255,.16); color: white; }

#exp-header-right { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }

/* ── RESPONSIVE ────────────────────────────────────────────────────── */
@media (max-width: 900px) {
  #exp-body    { grid-template-columns: 1fr; padding: 14px 16px 24px; }
  #inst-grid   { grid-template-columns: repeat(2, 1fr); }
  #period-grid { grid-template-columns: 1fr; }
}

@media (max-width: 700px) {
  #exp-header                       { padding: 10px 14px; }
  #exp-header-left                  { gap: 10px; }
  #exp-subtitle                     { display: none; }
  #exp-header-left > div:last-child { min-width: 0; overflow: hidden; }
  #exp-title     { font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 160px; }
  #exp-logo-text { font-size: 13px; }
  #exp-logo      { gap: 6px; }
  #exp-logo svg  { width: 16px; height: 20px; }
}

@media (max-width: 480px) {
  #exp-header-left > div:last-child { display: none; }
}

@media (max-width: 600px) {
  #exp-body   { padding: 10px 12px 20px; }
  #inst-grid  { grid-template-columns: 1fr; }
  #exp-right  { order: -1; }
  #quick-btns { flex-direction: column; }
  .quick-btn  { width: 100%; text-align: center; padding: 8px 11px; }
}

descriptor.controllerScript:
/**
 * CENTRO DE EXPORTACIÓN v2 — Controller Script
 * ThingsBoard PE 4.3.0PE · Sunkuu 360
 *
 * CAMBIOS respecto a v1:
 *   - DEVICES → INSTALLATIONS: instalaciones con múltiples dispositivos agrupados
 *   - Piscina Temperada: exporta de 3 dispositivos simultáneamente en un solo CSV
 *   - Variables agrupadas por categoría con etiquetas amigables
 *   - Keys actualizados a nombres reales confirmados en TB
 *   - Todas las funciones auxiliares (buildCSV, downloadCSV, fetchRaw, etc.) SIN cambios
 *
 * IDs de elementos HTML requeridos (deben existir en el template HTML):
 *   #inst-grid     → tarjetas de selección de instalación
 *   #var-groups    → contenedor de grupos de variables
 *   .var-chk       → checkboxes de variables (clase, no ID)
 *   #btn-all       → botón "Todas"
 *   #btn-none      → botón "Ninguna"
 *   #var-counter   → contador "X de Y seleccionadas"
 *   #dt-from       → input fecha desde
 *   #dt-to         → input fecha hasta
 *   .quick-btn     → botones de período rápido (con data-days)
 *   #sel-gran      → selector de granularidad
 *   #agg-wrap      → contenedor de agregación (clase disabled cuando raw)
 *   #raw-warning   → aviso de raw
 *   #sel-agg       → selector de agregación
 *   #summary-inst  → resumen: nombre instalación
 *   #summary-vars  → resumen: variables seleccionadas
 *   #summary-period→ resumen: período
 *   #summary-gran  → resumen: granularidad
 *   #summary-rows  → resumen: filas estimadas
 *   #btn-export    → botón exportar
 *   #btn-text      → texto del botón
 *   #btn-icon      → icono del botón
 *   #exp-progress  → contenedor de progreso
 *   #progress-fill → barra de progreso (width en %)
 *   #progress-label→ texto de progreso
 *   #exp-result    → mensaje de resultado
 *   #hist-list     → lista de historial
 */
self.onInit = function() {
  var ctx = self.ctx;
  self.ctx.$container.css({'overflow-y':'auto','height':'100%'});

  /* ── INSTALACIONES CON DISPOSITIVOS AGRUPADOS ─────────────────────── */
  /* Cada instalación puede tener 1 o más dispositivos.
   * Para instalaciones con un solo dispositivo (3EM), el array `devices`
   * tiene un solo elemento. Para Piscina, tiene tres.
   * Cada variable lleva `deviceIdx` indicando qué dispositivo del array usar. */

  var INSTALLATIONS = [
    {
      id: 'tg-gocta',
      label: 'TG Gocta',
      client: 'Gocta Andes Lodge',
      type: '3em',
      status: 'online',
      devices: [
        { id: 'c636fa00-2eeb-11f1-a6d8-33f75efe8b97', name: 'TG GOCTA' }
      ],
      varGroups: {
        'Potencia': [
          { k: 'potencia_activa_fase_a',    l: 'Pot. Activa Fase A',    di: 0 },
          { k: 'potencia_activa_fase_b',    l: 'Pot. Activa Fase B',    di: 0 },
          { k: 'potencia_activa_fase_c',    l: 'Pot. Activa Fase C',    di: 0 },
          { k: 'potencia_activa_total',     l: 'Pot. Activa Total',     di: 0 },
          { k: 'potencia_aparente_fase_a',  l: 'Pot. Aparente Fase A',  di: 0 },
          { k: 'potencia_aparente_fase_b',  l: 'Pot. Aparente Fase B',  di: 0 },
          { k: 'potencia_aparente_fase_c',  l: 'Pot. Aparente Fase C',  di: 0 },
          { k: 'potencia_aparente_total',   l: 'Pot. Aparente Total',   di: 0 }
        ],
        'Energía': [
          { k: 'energia_total',         l: 'Energía Total',           di: 0 },
          { k: 'energia_fase_a',        l: 'Energía Fase A',          di: 0 },
          { k: 'energia_fase_b',        l: 'Energía Fase B',          di: 0 },
          { k: 'energia_fase_c',        l: 'Energía Fase C',          di: 0 },
          { k: 'energia_ret_total',     l: 'Energía Devuelta Total',  di: 0 },
          { k: 'energia_ret_fase_a',    l: 'Energía Dev. Fase A',     di: 0 },
          { k: 'energia_ret_fase_b',    l: 'Energía Dev. Fase B',     di: 0 },
          { k: 'energia_ret_fase_c',    l: 'Energía Dev. Fase C',     di: 0 }
        ],
        'Calidad Eléctrica': [
          { k: 'voltaje_fase_a',            l: 'Voltaje Fase A',         di: 0 },
          { k: 'voltaje_fase_b',            l: 'Voltaje Fase B',         di: 0 },
          { k: 'voltaje_fase_c',            l: 'Voltaje Fase C',         di: 0 },
          { k: 'corriente_fase_a',          l: 'Corriente Fase A',       di: 0 },
          { k: 'corriente_fase_b',          l: 'Corriente Fase B',       di: 0 },
          { k: 'corriente_fase_c',          l: 'Corriente Fase C',       di: 0 },
          { k: 'factor_potencia_fase_a',    l: 'Factor Pot. Fase A',     di: 0 },
          { k: 'factor_potencia_fase_b',    l: 'Factor Pot. Fase B',     di: 0 },
          { k: 'factor_potencia_fase_c',    l: 'Factor Pot. Fase C',     di: 0 }
        ]
      }
    },
    {
      id: 'tg-pumarinri',
      label: 'TG Pumarinri',
      client: 'Gocta Andes Lodge',
      type: '3em',
      status: 'online',
      devices: [
        { id: 'cf7ddac0-2eeb-11f1-a6d8-33f75efe8b97', name: 'TG PUMARINRI' }
      ],
      varGroups: {
        'Potencia': [
          { k: 'potencia_activa_fase_a',    l: 'Pot. Activa Fase A',    di: 0 },
          { k: 'potencia_activa_fase_b',    l: 'Pot. Activa Fase B',    di: 0 },
          { k: 'potencia_activa_fase_c',    l: 'Pot. Activa Fase C',    di: 0 },
          { k: 'potencia_activa_total',     l: 'Pot. Activa Total',     di: 0 },
          { k: 'potencia_aparente_fase_a',  l: 'Pot. Aparente Fase A',  di: 0 },
          { k: 'potencia_aparente_fase_b',  l: 'Pot. Aparente Fase B',  di: 0 },
          { k: 'potencia_aparente_fase_c',  l: 'Pot. Aparente Fase C',  di: 0 },
          { k: 'potencia_aparente_total',   l: 'Pot. Aparente Total',   di: 0 }
        ],
        'Energía': [
          { k: 'energia_total',         l: 'Energía Total',           di: 0 },
          { k: 'energia_fase_a',        l: 'Energía Fase A',          di: 0 },
          { k: 'energia_fase_b',        l: 'Energía Fase B',          di: 0 },
          { k: 'energia_fase_c',        l: 'Energía Fase C',          di: 0 },
          { k: 'energia_ret_total',     l: 'Energía Devuelta Total',  di: 0 },
          { k: 'energia_ret_fase_a',    l: 'Energía Dev. Fase A',     di: 0 },
          { k: 'energia_ret_fase_b',    l: 'Energía Dev. Fase B',     di: 0 },
          { k: 'energia_ret_fase_c',    l: 'Energía Dev. Fase C',     di: 0 }
        ],
